# [macro_use] extern crate rocket ; use rocket :: response :: stream :: TextStream ; use rocket :: tokio :: time :: { self , Duration } ; # [doc = " Produce an infinite series of `\"hello\"`s, one per second."] # [get ("/infinite-hellos")] fn hello () -> TextStream ! [&'static str] { TextStream ! { let mut interval = time :: interval (Duration :: from_secs (1)) ; loop { yield "hello" ; interval . tick () . await ; } } } # [launch] fn rocket () -> _ { rocket :: build () . mount ("/" , routes ! [hello]) }